import{_ as r,o,c as n,a5 as a}from"./chunks/framework.Cooo9kuv.js";const c=JSON.parse('{"title":"程序使用环境及相关说明","description":"","frontmatter":{"标题":"801-拖入文件夹自动压缩为压缩包V3.0","日期":"2026-05-23T00:00:00.000Z","修改日期":"2026-05-23T00:00:00.000Z","作者":"softbangong","状态":"publish","分类":["压缩包批处理"],"标签":["softbangong","办公文件整理","压缩包密码管理","压缩包自动加密","批量压缩软件","文件分发助手","文件夹批量压缩","文件筛选压缩","文件逐个打包","资料归档工具"]},"headers":[],"relativePath":"md/压缩包批处理/801-拖入文件夹自动压缩为压缩包V3.0.md","filePath":"md/压缩包批处理/801-拖入文件夹自动压缩为压缩包V3.0.md"}'),s={name:"md/压缩包批处理/801-拖入文件夹自动压缩为压缩包V3.0.md"};function p(g,t,e,h,i,l){return o(),n("div",null,[...t[0]||(t[0]=[a('<p>这个工具可以把你拖进来的文件夹里的每个文件和子文件夹分别压缩成独立的压缩包，支持7z、zip、rar三种格式，还能给压缩包设置密码、添加URL快捷方式或文本文件一起打包。</p><p>你只需要把文件夹拖进窗口，点一下压缩按钮，程序就会自动帮你把所有文件一个个打包好，还会自动生成密码记录文件，省去你手动逐个压缩的麻烦。</p><p><img src="https://www.softbangong.com/wp-content/uploads/2026/05/image-19.png" alt=""></p><h3 id="功能特点" tabindex="-1">功能特点 <a class="header-anchor" href="#功能特点" aria-label="Permalink to &quot;功能特点&quot;">​</a></h3><p><strong>逐个独立压缩</strong>：文件夹根目录下的每个文件和子文件夹都会被分别压缩成独立的压缩包，不会把所有文件打包成一个。</p><p><strong>三种压缩格式</strong>：支持7z、zip、rar三种主流压缩格式，你可以根据需要自由选择。</p><p><strong>灵活密码管理</strong>：支持无密码、统一密码、密码库文件三种方式。密码库文件每行一个密码，程序会按顺序依次分配给每个压缩包，用完后自动更新密码库。</p><p><strong>额外内容打包</strong>：可以在压缩时额外添加URL快捷方式、文本文件、其他文件或文件夹，这些内容会直接打包进每个压缩包内，不会在原文件夹中创建实体文件。</p><p><img src="https://www.softbangong.com/wp-content/uploads/2026/05/image-23.png" alt=""></p><p><strong>自动密码记录</strong>：压缩完成后会自动记录每个压缩包对应的解压密码，方便你日后查找。</p><p><strong>批量处理支持</strong>：支持同时添加多个文件夹进行压缩，拖拽列表和批量列表中的文件夹都会被处理。</p><p><strong>配置自动保存</strong>：你的设置会自动保存到配置文件中，下次打开程序时自动恢复上次的选择。</p><p><strong>智能筛选规则</strong>：支持按文件夹、所有文件、指定扩展名进行筛选，只压缩符合条件的项目，可同时配置多条规则。</p><p><strong>批量扫描子文件夹</strong>：可以选择一个父文件夹，一键扫描其下所有一级子文件夹并添加到批量列表。</p><p><strong>额外项目配置管理</strong>：支持保存和导入额外添加项目的JSON配置文件，方便重复使用相同配置。</p><p><strong>额外项目编辑功能</strong>：已添加的URL、文本、文件、文件夹都支持再次编辑修改。</p><p><strong>智能滚轮分发</strong>：鼠标在不同区域滚动时自动识别，内部区域独立滚动，互不干扰。</p><h3 id="基本操作指南" tabindex="-1">基本操作指南 <a class="header-anchor" href="#基本操作指南" aria-label="Permalink to &quot;基本操作指南&quot;">​</a></h3><h3 id="操作1-压缩单个文件夹" tabindex="-1">操作1：压缩单个文件夹 <a class="header-anchor" href="#操作1-压缩单个文件夹" aria-label="Permalink to &quot;操作1：压缩单个文件夹&quot;">​</a></h3><p><strong>第一步</strong>，把要压缩的文件夹拖拽到拖拽列表区域，或者点击浏览按钮选择文件夹添加到批量列表。</p><p><strong>第二步</strong>，在格式选择下拉菜单中选择你想要的压缩格式，可选7z、zip或rar。</p><p><strong>第三步</strong>，选择密码方式。如果不需要密码就选无密码，如果要统一密码就选统一密码并在输入框中输入密码，如果要每个文件不同密码就选密码库文件并选择你的txt密码文件。</p><p><strong>第四步</strong>，点击开始压缩按钮，等待日志区域显示压缩完成。</p><hr><p>示例：你想把 <strong>E:\\工作资料</strong> 文件夹里的每个文件分别压缩成7z格式，并且都加上密码 <strong>123456</strong>。</p><p>你把 <strong>E:\\工作资料</strong> 拖进拖拽列表区域，格式选择 <strong>7z</strong>，密码方式选择 <strong>统一密码</strong>，在密码输入框输入 <strong>123456</strong>，然后点击开始压缩按钮。</p><p>压缩完成后，在 *<em>E:*</em> 目录下会出现一个名为 <strong>工作资料-压缩包及解压密码</strong> 的文件夹，里面每个文件都有自己独立的子文件夹，子文件夹里就是对应的7z压缩包，同时还有一个密码记录文件。</p><hr><h3 id="操作2-使用密码库文件" tabindex="-1">操作2：使用密码库文件 <a class="header-anchor" href="#操作2-使用密码库文件" aria-label="Permalink to &quot;操作2：使用密码库文件&quot;">​</a></h3><p><strong>第一步</strong>，准备一个txt格式的密码库文件，每行写一个密码，例如第一行写 <strong>abc123</strong>，第二行写 <strong>def456</strong>，第三行写 <strong>ghi789</strong>。</p><p><strong>第二步</strong>，把要压缩的文件夹添加到列表中。</p><p><strong>第三步</strong>，密码方式选择 <strong>密码库文件</strong>，点击浏览按钮选择你准备好的txt密码文件。</p><p><strong>第四步</strong>，点击开始压缩按钮，程序会按顺序把密码库里的密码依次分配给每个压缩包。</p><hr><p>示例：你的文件夹里有5个文件，密码库文件里有8个密码。</p><p>程序会把密码库的前5个密码分别给5个压缩包使用，压缩完成后密码库文件会自动更新，只剩下剩余的3个密码，下次使用接着从剩下的密码开始分配。</p><p>压缩完成后会生成一个密码记录文件，里面清楚记录了每个压缩包用的是哪个密码，你不用担心忘记对应关系。</p><hr><h3 id="操作3-添加额外内容到压缩包" tabindex="-1">操作3：添加额外内容到压缩包 <a class="header-anchor" href="#操作3-添加额外内容到压缩包" aria-label="Permalink to &quot;操作3：添加额外内容到压缩包&quot;">​</a></h3><p><strong>第一步</strong>，在额外添加区域选择要添加的类型，可以是URL链接、文本内容、文件或文件夹。</p><p><strong>第二步</strong>，输入URL地址或文本内容，或者浏览选择要添加的文件或文件夹。你也可以自定义文件名，不填的话程序会自动生成。</p><p><strong>第三步</strong>，点击添加按钮，额外项目会显示在列表中。</p><p><strong>第四步</strong>，正常执行压缩操作，这些额外内容会被打包进每个压缩包内。</p><hr><p>示例：你想给每个压缩包都附带一个公司官网链接和一段使用说明。</p><p>你在额外添加区域选择 <strong>URL</strong> 类型，输入 <strong><a href="https://www.example.com/" target="_blank" rel="noreferrer">https://www.example.com</a></strong>，自定义文件名填 <strong>公司官网</strong>，点击添加。然后选择 <strong>文本</strong> 类型，输入使用说明内容，自定义文件名填 <strong>使用说明</strong>，点击添加。</p><p>压缩完成后，每个压缩包解压出来都会包含一个 <strong>公司官网.url</strong> 快捷方式文件和一个 <strong>使用说明.txt</strong> 文本文件，不需要你手动去每个文件夹里创建。</p><hr><h3 id="操作4-使用筛选规则" tabindex="-1">操作4：使用筛选规则 <a class="header-anchor" href="#操作4-使用筛选规则" aria-label="Permalink to &quot;操作4：使用筛选规则&quot;">​</a></h3><p><strong>第一步</strong>，在筛选规则区域选择规则类型，可以是folder（文件夹）、file（所有文件）或ext（指定扩展名）。</p><p><strong>第二步</strong>，如果选择了ext类型，需要在扩展名输入框中输入扩展名，多个扩展名用逗号分隔，例如 <strong>.py,.txt,.docx</strong>。</p><p><strong>第三步</strong>，点击添加规则按钮，规则会显示在规则列表中。你可以添加多条规则，规则之间是“或”的关系，只要匹配任一规则就会被压缩。</p><p><strong>第四步</strong>，正常执行压缩操作，程序只会压缩符合筛选规则的项目。</p><hr><p>示例：你的文件夹里有100个文件，包括.py、.txt、.jpg等多种类型，但你只想压缩.py和.txt文件。</p><p>你在筛选规则区域选择 <strong>ext</strong> 类型，输入 <strong>.py,.txt</strong>，点击添加规则。然后点击开始压缩按钮。</p><p>程序会扫描文件夹，发现100个项目中只有30个是.py或.txt文件，日志会显示“100个项目经筛选后保留30个”，然后只压缩这30个文件，其他70个文件会被忽略。</p><hr><h3 id="操作5-批量扫描子文件夹" tabindex="-1">操作5：批量扫描子文件夹 <a class="header-anchor" href="#操作5-批量扫描子文件夹" aria-label="Permalink to &quot;操作5：批量扫描子文件夹&quot;">​</a></h3><p><strong>第一步</strong>，在批量操作标签页中，点击浏览按钮选择一个包含多个子文件夹的父文件夹。</p><p><strong>第二步</strong>，点击扫描子文件夹按钮，程序会自动扫描该父文件夹下所有一级子文件夹。</p><p><strong>第三步</strong>，扫描完成后，所有一级子文件夹会添加到批量列表中，你可以在列表中看到所有子文件夹的路径。</p><p><strong>第四步</strong>，正常执行压缩操作，批量列表中的所有子文件夹都会被处理。</p><hr><p>示例：你有一个 <strong>E:\\项目资料</strong> 文件夹，里面有50个子文件夹，每个子文件夹都是一个独立项目的资料。</p><p>你在批量操作标签页点击浏览，选择 <strong>E:\\项目资料</strong>，然后点击扫描子文件夹按钮。程序会找到50个子文件夹并全部添加到批量列表。</p><p>点击开始压缩按钮后，这50个子文件夹都会被分别压缩，每个子文件夹生成独立的压缩包和密码记录。</p><hr><h3 id="操作6-保存和导入额外项目配置" tabindex="-1">操作6：保存和导入额外项目配置 <a class="header-anchor" href="#操作6-保存和导入额外项目配置" aria-label="Permalink to &quot;操作6：保存和导入额外项目配置&quot;">​</a></h3><p><strong>第一步</strong>，在额外添加区域添加好你需要的项目，比如URL链接、文本内容、文件或文件夹。</p><p><strong>第二步</strong>，在配置输入框中输入要保存的路径和文件名，或者留空不填。</p><p><strong>第三步</strong>，点击保存配置按钮。如果配置输入框为空，会弹出保存对话框让你选择保存位置。配置文件为JSON格式。</p><p><strong>第四步</strong>，下次使用时，点击导入配置按钮，选择之前保存的JSON文件，所有额外项目会自动导入到列表中。</p><hr><p>示例：你经常需要给每个压缩包添加公司官网链接、客服联系方式和使用说明文本。</p><p>你第一次使用时，在额外添加区域添加了URL类型（公司官网）、URL类型（客服联系方式）、文本类型（使用说明）。然后点击保存配置按钮，保存为 <strong>常用配置.json</strong>。</p><p>下次使用时，你不需要再逐个添加，直接点击导入配置按钮，选择 <strong>常用配置.json</strong>，所有项目瞬间导入完成，省时省力。</p><h3 id="实际使用场景示例" tabindex="-1">实际使用场景示例 <a class="header-anchor" href="#实际使用场景示例" aria-label="Permalink to &quot;实际使用场景示例&quot;">​</a></h3><h3 id="场景1-教师打包课程资料发给学生" tabindex="-1">场景1：教师打包课程资料发给学生 <a class="header-anchor" href="#场景1-教师打包课程资料发给学生" aria-label="Permalink to &quot;场景1：教师打包课程资料发给学生&quot;">​</a></h3><p>场景描述：你是老师，期末了需要把一学期的课件、作业、试卷等20多个文件分别压缩成独立的压缩包发给学生，每个文件都要设置不同的密码保证安全性。</p><p><strong>第一步</strong>，在桌面新建一个txt文件，里面写20行不同的密码，每行一个。</p><p><strong>第二步</strong>，打开程序，把存放课程资料的文件夹拖进拖拽列表区域。</p><p><strong>第三步</strong>，格式选择 <strong>7z</strong>，密码方式选择 <strong>密码库文件</strong>，浏览选择你刚才创建的密码txt文件。</p><p><strong>第四步</strong>，点击开始压缩按钮，等待压缩完成。</p><p>预期结果：在课程资料文件夹所在目录会出现一个 <strong>课程资料-压缩包及解压密码</strong> 的文件夹，里面有20个子文件夹，每个子文件夹里有一个压缩包和对应的密码，同时还有一个密码记录文件汇总了所有压缩包和密码的对应关系，你直接把整个文件夹发给学生就行。</p><hr><h3 id="场景2-设计师给客户发送设计稿" tabindex="-1">场景2：设计师给客户发送设计稿 <a class="header-anchor" href="#场景2-设计师给客户发送设计稿" aria-label="Permalink to &quot;场景2：设计师给客户发送设计稿&quot;">​</a></h3><p>场景描述：你是设计师，给客户做了10张设计图，需要把每张图单独压缩并附带一个公司官网链接和使用说明文档一起发给客户。</p><p><strong>第一步</strong>，把存放设计图的文件夹拖进拖拽列表区域。</p><p><strong>第二步</strong>，格式选择 <strong>zip</strong>（兼容性最好，客户不需要额外安装解压软件），密码方式选择 <strong>统一密码</strong>，输入密码 <strong>design2024</strong>。</p><p><strong>第三步</strong>，在额外添加区域添加URL类型，输入公司官网地址，自定义文件名填 <strong>公司官网</strong>。再添加文本类型，输入使用说明内容，自定义文件名填 <strong>使用须知</strong>。</p><p><strong>第四步</strong>，点击开始压缩按钮。</p><p>预期结果：生成的10个zip压缩包每个都包含了设计图文件、公司官网快捷方式和使用须知文本文件，客户解压后能直接看到所有相关内容，不需要你额外发送说明文件。</p><hr><h3 id="场景3-行政人员归档工作资料" tabindex="-1">场景3：行政人员归档工作资料 <a class="header-anchor" href="#场景3-行政人员归档工作资料" aria-label="Permalink to &quot;场景3：行政人员归档工作资料&quot;">​</a></h3><p>场景描述：你是行政人员，每个月都要把各部门提交的工作报告、发票、凭证等文件归档，需要压缩保存并记录每个文件的解压密码，方便日后查找。</p><p><strong>第一步</strong>，把当月的工作资料文件夹拖进拖拽列表区域。</p><p><strong>第二步</strong>，格式选择 <strong>rar</strong>，密码方式选择 <strong>密码库文件</strong>，选择你维护的密码库文件。</p><p><strong>第三步</strong>，保存位置选择 <strong>指定目录</strong>，浏览选择你专门用来存放归档压缩包的硬盘分区。</p><p><strong>第四步</strong>，点击开始压缩按钮。</p><p>预期结果：所有文件被分别压缩后保存到你指定的目录，每个压缩包在自己的子文件夹里，密码记录文件汇总了所有密码，密码库文件自动扣除了已使用的密码。你只需要把这个月的归档文件夹重命名后保存就行，下次归档接着用剩余的密码。</p><h3 id="数据存储位置" tabindex="-1">数据存储位置 <a class="header-anchor" href="#数据存储位置" aria-label="Permalink to &quot;数据存储位置&quot;">​</a></h3><p><strong>压缩包及密码文件夹</strong>：默认保存在原文件夹所在的目录，文件夹名称为 <strong>原文件夹名-压缩包及解压密码</strong>。如果选择了指定目录保存，则保存在你选择的目标目录。</p><p><strong>单个压缩包</strong>：每个压缩包都存放在 <strong>压缩包及密码文件夹</strong> 内以原文件名命名的子文件夹中。</p><p><strong>密码记录文件</strong>：保存在 <strong>压缩包及密码文件夹</strong> 内，文件名为 <strong>原文件夹名-压缩包解压密码.txt</strong>。</p><p><strong>程序配置文件</strong>：保存在程序同级目录下的 <strong>app_config.json</strong> 文件中，记录你的密码库路径等设置。</p><h3 id="常见问题解答" tabindex="-1">常见问题解答 <a class="header-anchor" href="#常见问题解答" aria-label="Permalink to &quot;常见问题解答&quot;">​</a></h3><h3 id="问题1-点击开始压缩按钮后没有反应怎么办" tabindex="-1">问题1：点击开始压缩按钮后没有反应怎么办 <a class="header-anchor" href="#问题1-点击开始压缩按钮后没有反应怎么办" aria-label="Permalink to &quot;问题1：点击开始压缩按钮后没有反应怎么办&quot;">​</a></h3><p>答案：先检查拖拽列表和批量列表是否为空，两个列表都没有文件夹的话程序不会执行压缩。然后查看日志区域是否有错误提示，常见错误是压缩软件路径不正确或文件夹路径无效。如果日志显示压缩软件未找到，说明没有将apitool文件夹复制到C盘</p><p><img src="https://www.softbangong.com/wp-content/uploads/2026/05/image-20.png" alt=""></p><hr><h3 id="问题2-压缩包解压时提示密码错误" tabindex="-1">问题2：压缩包解压时提示密码错误 <a class="header-anchor" href="#问题2-压缩包解压时提示密码错误" aria-label="Permalink to &quot;问题2：压缩包解压时提示密码错误&quot;">​</a></h3><p>答案：打开压缩包所在文件夹里的密码记录文件 <strong>原文件夹名-压缩包解压密码.txt</strong>，找到对应压缩包的密码。密码记录文件的格式是压缩包名称一行，接着 <strong>压缩包解压密码</strong> 标签行，再一行是解压密码，每个压缩包占三行，各压缩包之间用空行分隔。如果密码记录文件里没有对应密码，说明压缩时使用的是无密码方式。</p><hr><h3 id="问题3-密码库文件里的密码不够用怎么办" tabindex="-1">问题3：密码库文件里的密码不够用怎么办 <a class="header-anchor" href="#问题3-密码库文件里的密码不够用怎么办" aria-label="Permalink to &quot;问题3：密码库文件里的密码不够用怎么办&quot;">​</a></h3><p>答案：程序会按顺序使用密码库里的密码，用完后剩余的压缩包会使用无密码方式压缩。你可以在密码库里多准备一些密码，确保数量大于等于文件夹里的文件数量。压缩完成后密码库文件会自动更新，只保留未使用的密码，你可以随时往密码库里添加新密码。</p><hr><h3 id="问题4-额外添加的url或文本文件能在原文件夹里看到吗" tabindex="-1">问题4：额外添加的URL或文本文件能在原文件夹里看到吗 <a class="header-anchor" href="#问题4-额外添加的url或文本文件能在原文件夹里看到吗" aria-label="Permalink to &quot;问题4：额外添加的URL或文本文件能在原文件夹里看到吗&quot;">​</a></h3><p>答案：不能。额外添加的URL快捷方式和文本文件是在临时目录创建的，直接打包进压缩包内，不会在你的原文件夹中留下任何痕迹。压缩完成后临时文件会被自动清理，原文件夹保持原样不受影响。</p><hr><h3 id="问题5-可以同时压缩多个文件夹吗" tabindex="-1">问题5：可以同时压缩多个文件夹吗 <a class="header-anchor" href="#问题5-可以同时压缩多个文件夹吗" aria-label="Permalink to &quot;问题5：可以同时压缩多个文件夹吗&quot;">​</a></h3><p>答案：可以。你可以往拖拽列表区域拖拽多个文件夹，也可以通过浏览按钮往批量列表添加多个文件夹。两个列表中的文件夹都会被处理，每个文件夹都会生成独立的压缩包及密码文件夹。</p><p><img src="https://www.softbangong.com/wp-content/uploads/2026/05/image-22.png" alt=""></p><hr><h3 id="问题6-压缩格式选错了能重新压缩吗" tabindex="-1">问题6：压缩格式选错了能重新压缩吗 <a class="header-anchor" href="#问题6-压缩格式选错了能重新压缩吗" aria-label="Permalink to &quot;问题6：压缩格式选错了能重新压缩吗&quot;">​</a></h3><p>答案：可以。压缩完成后原文件夹不会被修改或删除，你可以重新选择格式再次压缩。每次压缩都会生成新的输出文件夹，不会覆盖之前的结果。建议确认格式无误后再压缩，避免重复操作浪费时间。</p><hr><h3 id="问题7-筛选规则是如何工作的" tabindex="-1">问题7：筛选规则是如何工作的 <a class="header-anchor" href="#问题7-筛选规则是如何工作的" aria-label="Permalink to &quot;问题7：筛选规则是如何工作的&quot;">​</a></h3><p>答案：筛选规则采用“或”逻辑，只要项目匹配任意一条规则就会被压缩。folder规则匹配所有文件夹，file规则匹配所有文件，ext规则匹配指定扩展名的文件。如果没有任何筛选规则，默认压缩全部项目。扩展名输入支持逗号分隔多个，例如 <strong>.py,.txt,.docx</strong> 会匹配所有这三种扩展名的文件。</p><p><img src="https://www.softbangong.com/wp-content/uploads/2026/05/image-21.png" alt=""></p><hr><h3 id="问题8-密码库文件的密码用完后会怎样" tabindex="-1">问题8：密码库文件的密码用完后会怎样 <a class="header-anchor" href="#问题8-密码库文件的密码用完后会怎样" aria-label="Permalink to &quot;问题8：密码库文件的密码用完后会怎样&quot;">​</a></h3><p>答案：程序会按顺序使用密码库里的密码，密码用完后，剩余的压缩包会使用无密码方式压缩。你可以在密码库里多准备一些密码，确保数量大于等于需要压缩的文件数量。压缩完成后密码库文件会自动更新，只保留未使用的密码，你可以随时往密码库里添加新密码。</p><h1 id="程序使用环境及相关说明" tabindex="-1">程序使用环境及相关说明 <a class="header-anchor" href="#程序使用环境及相关说明" aria-label="Permalink to &quot;程序使用环境及相关说明&quot;">​</a></h1><p><strong>1、适用的系统环境说明</strong>：</p><p>win7及以上64位windows操作系统 ，  **注意事项：**win32位系统以及mac系统需要额外定制开发</p><p><strong>2、关于使用限制</strong>：</p><p>①无需注册、登录等限制，直接使用，  ②没有电脑台数限制，  ③无使用时间限制、不联网本地使用、确保数据安全</p><p>**3、程序如何安装：**不需要安装，按照说明使用即可。</p><p><strong>特别注意</strong>：请先测试，注意备份原文件，之后再批量使用，避免不可逆损失。</p><h1 id="程序使用说明" tabindex="-1">程序使用说明 <a class="header-anchor" href="#程序使用说明" aria-label="Permalink to &quot;程序使用说明&quot;">​</a></h1><p><strong>解压后将apitool文件夹复制到C盘根目录即可，双击exe程序直接使用即可，不需要安装，程序可以放在任意位置</strong></p><p><img src="https://www.softbangong.com/wp-content/uploads/2026/05/image-24.png" alt=""></p><h2 id="更新日志" tabindex="-1">更新日志： <a class="header-anchor" href="#更新日志" aria-label="Permalink to &quot;更新日志：&quot;">​</a></h2><p>优化更新-可以全局保存配置，导入配置，配置手动复制修改名称后导入到程序</p><p><img src="https://www.softbangong.com/wp-content/uploads/2026/05/image-25.png" alt=""></p><hr><p><strong>程序下载链接：</strong> <a href="https://www.softbangong.com/2814.html" target="_blank" rel="noreferrer">https://www.softbangong.com/2814.html</a></p>',148)])])}const m=r(s,[["render",p]]);export{c as __pageData,m as default};
